#if FOO
extension Diagnostic {
  /// Construct a new diagnostic that has exactly one Fix-It.
  public init(
    node: some SyntaxProtocol,
    position: AbsolutePosition? = nil,
    message: DiagnosticMessage,
    highlights: [c]? /*c*/= nil,
    notes: [Note] = [],
    fixIt: FixIt
  ) {
    self.init(
      node:  node,
      position: position,
      message: message,
      highlights: highlights,
      notes: notes,
      fixIts: [fixIt]
    )
  }
}
#endif

